  ('rev_2', 'est_cras_esperanca', 'usr_visitante', 'Mariana Silva', 'Usuária de Cadeira de Rodas', true, 5, 'Equipe do CRAS extremamente empática e atenciosa! Rampa suave, banheiro espaçoso com barras firmes e atendimento sem qualquer preconceito.', '{"physical":95,"intellectual":90,"sensory":85,"visual":90,"auditory":90,"service":100}'::jsonb, '[]'::jsonb, '[]'::jsonb, 'presencial', 'aprovada', '2026-11-12T10:15:00Z')
